// pick_drug (Select By Form → Trade Drug) → onChange   [ฟอร์ม cpoe_order_item]
//
// 🔑 ไม่ต้อง join / ไม่ต้องยิง provider — `trade.gp_ref` เป็น snapshot ของ Generic ที่ติดมากับ Trade อยู่แล้ว
//    (sigs · subs · dose_form · disp_unit · vtm · gp_id · label = ชื่อ generic)
//    ขอแค่ตั้ง refField ของ field นี้ให้ดึงมา แล้วค่าจะอยู่ใน `value` ตั้งแต่ตอน onChange เลย
//
// ต้องตั้งที่ field pick_drug (select-form → Trade Drug):
//   valueField  : _id            · valueObjectId: true · fileterObjectId: true
//   labelField  : ["item_name","item_code"]   (หรือ labelTemplate)
//   searchField : ["item_code","item_name","synonyms","gp_ref.label"]   ← ค้นชื่อ generic ผ่าน gp_ref.label
//   refField    : ["gp_ref","price_data","disp_unit","disp_qty","edit_price","restricted","item_code","item_name","trade_name","gpu_id","tp_id","tpu_id"]
//
// 🔴 ต้องไปเพิ่ม refField ของ field `gp_ref` ในฟอร์ม **Trade Drug** ก่อนด้วย:
//    ปัจจุบันมี gp_id · vtm · subs · dose_form · disp_unit · sigs
//    ต้องเพิ่ม → atc · drug_control · drug_type · strength · code   (ไม่งั้น 5 ช่องนี้ใน drug_ref จะว่าง)
//
// ⚠️ gp_ref เป็น snapshot ตอน save Trade Drug — แก้ Generic ทีหลังจะไม่อัปเดตจนกว่าจะ save trade ใหม่
//    (เคาะ 2026-08-03 ว่ารับได้ · ใบสั่งต้องการค่า ณ ตอนสั่งอยู่แล้ว ไม่ใช่ค่าล่าสุด)

const TRADE_FORM_ID = '6a5fb732a608039c539ebb4f'; // ฟอร์ม Trade Drug

const form = this.getFormRef();
const drug = value;
if (!drug || !drug.value) return; // clear → ไม่แตะค่าเดิม

const gp = drug.gp_ref || {};
if (!gp.sigs && !gp.subs) {
	// refField ยังไม่ได้ตั้ง → ค่าจะว่างทั้งกล่อง ต้องรู้ทันที ไม่ใช่ไปงงตอนกดบันทึก
	console.warn('[pick_drug] ไม่พบ gp_ref — ตรวจ refField ของ field pick_drug ว่ามี "gp_ref" หรือยัง');
}

// ---------- helpers ----------------------------------------------------------
const setF = (name, val) => {
	// แยก try/catch ต่อ field — field ที่ onChange ตัวเองพัง ต้องไม่บล็อกตัวอื่น (pattern เดียวกับ gp onChange)
	const f = this.refField(name);
	if (!f || !f.setValue) return;
	try {
		f.setValue(val);
	} catch (e) {
		console.warn('[pick_drug] setValue ' + name + ' failed:', e);
	}
};

// object-group (drug_ref / prescription_data) — field ข้างในผูกกับ formModel[<group>][<field>] ให้เองแล้ว
// (CoreFieldMixin:693) ⇒ setValue ทีละช่องได้ตรงๆ
// 🔴 ห้ามใช้ form.setFormData() — broadcast global + rebuild ทุก sub-form
//    → :params ของ select เปลี่ยน → re-fetch วนไม่จบ = จอค้าง (เคยเกิดที่ gp onChange)
const setGroup = (obj) => {
	Object.keys(obj).forEach((k) => setF(k, obj[k]));
};

// ค่าที่มาจาก select เป็น { value, label } — เก็บลง text-input ทั้งก้อนจะได้ [object Object]
// ⇒ แยก code (ระบบใช้เทียบ) กับ label (คนอ่าน) เป็นคนละช่อง
const code = (v) => (v && typeof v === 'object' ? (Array.isArray(v.value) ? v.value.join(',') : (v.value ?? null)) : (v ?? null));
const text = (v) => (v && typeof v === 'object' ? (v.label ?? v.name_th ?? null) : (v ?? null));

const num = (v) => {
	const n = Number(v);
	return isNaN(n) ? 0 : n;
};

// strength ของ generic = [{s_ingredient, s_dose, s_unit:{value,label}}] → ย่อเป็นบรรทัดเดียวที่คนอ่านได้
// (เก็บเป็นข้อความ ไม่ใช่ sub-form — ในใบสั่งยาความแรงเป็นข้อมูลอ้างอิง ไม่ได้เอาไปคำนวณต่อ)
const strengthText = (arr) => {
	if (!Array.isArray(arr) || arr.length === 0) return null;
	return arr
		.map((x) => [x.s_ingredient, x.s_dose, text(x.s_unit)].filter((p) => p !== null && p !== undefined && p !== '').join(' '))
		.join(' + ');
};

// สิทธิ์ของใบ — ฟอร์มลูกรับมาทาง formParams ที่ใบแม่ส่งเข้ามาตอนเปิด
// (โครงเดียวกับ visit.inscl_hos[] เป๊ะ: { inscl_item_main:{value}, inscl_item_sub:{value} })
const getOrderInscl = () => {
	const p = form.formParams || {};
	const list = p.inscl_hos;
	if (Array.isArray(list) && list.length > 0) return list[0];
	if (p.inscl_item_main || p.inscl_item_sub) return p;
	return null;
};

// ราคาตามสิทธิ์ (D9) — ไม่เจอสิทธิ์/ไม่เจอราคาของสิทธิ์นั้น = ชำระเอง (จ่ายเต็ม เบิก 0)
const pickPrice = (priceData, inscl) => {
	const rows = Array.isArray(priceData) ? priceData : [];
	const mainV = inscl && inscl.inscl_item_main ? inscl.inscl_item_main.value : null;
	const subV = inscl && inscl.inscl_item_sub ? inscl.inscl_item_sub.value : null;

	let hit = null;
	if (mainV) {
		hit = rows.find((r) => {
			const rm = r && r.inscl_main ? r.inscl_main.value : null;
			const rs = r && r.inscl_sub ? r.inscl_sub.value : null;
			return rm === mainV && (!subV || !rs || rs === subV);
		});
	}
	if (hit) return { unit: num(hit.sell_price), claim: num(hit.cover_price), cash: false };

	// ชำระเอง — ใช้ราคาขายแถวแรกที่มีเป็นราคากลาง แล้วเบิก 0
	// ⚠️ ข้อสมมติ: price_data จริงไม่มีแถว CASH (D12 ข้อ 1 ยังไม่เคาะว่า "ราคากลาง" อ่านจากไหน)
	const base = rows.length > 0 ? num(rows[0].sell_price) : 0;
	return { unit: base, claim: 0, cash: true };
};

// ---------- 1) ตัวชี้รายการ (polymorphic) ----------
setF('item_source', 'drug');
setF('item_form_id', TRADE_FORM_ID);
setF('item_data_id', String(drug.value));
setF('item_code', drug.item_code || null);
setF('item_name', drug.item_name || drug.trade_name || drug.label || null);
setF('service_type', { value: 'med', label: 'Medicine' });

// ---------- 2) drug_ref — snapshot ของยา ----------
// 🔴 snapshot ทั้งชุดตอนเลือก ห้าม resolve สดตอนเปิดใบเก่า —
//    master ถูกแก้ทีหลัง (เปลี่ยนความแรง/เลิกใช้) ใบเก่าต้องยังอ่านออกว่าตอนนั้นสั่งอะไร
setGroup({
	trade_name: drug.trade_name || drug.item_name || null,
	generic_name: gp.label || null,                       // gp_ref.label = ชื่อ generic เต็ม
	generic_code: gp.code || null,                        // ← ต้องเพิ่ม 'code' ใน refField ของ gp_ref
	subs_ids: gp.subs && Array.isArray(gp.subs.value) ? gp.subs.value : [], // 🔴 กฎ drug-check เทียบช่องนี้
	vtm_id: code(gp.vtm),
	gp_id: code(gp.gp_id),
	gpu_id: drug.gpu_id || null,
	tp_id: code(drug.tp_id),
	tpu_id: drug.tpu_id || null,
	atc: code(gp.atc),                                    // ← ต้องเพิ่ม 'atc' ใน refField ของ gp_ref
	disp_unit: code(drug.disp_unit || gp.disp_unit),
	disp_unit_label: text(drug.disp_unit || gp.disp_unit),
	dose_form: code(gp.dose_form),
	dose_form_label: text(gp.dose_form),
	strength_text: strengthText(gp.strength),             // ← ต้องเพิ่ม 'strength' ใน refField ของ gp_ref
	drug_control: text(gp.drug_control),                  // ← ต้องเพิ่ม 'drug_control'
	drug_type: code(gp.drug_type),                        // ← ต้องเพิ่ม 'drug_type'
});

// ---------- 3) prescription_data — 1 ชุดจาก sigs[] ----------
// sigs = template วิธีใช้ที่เภสัชตั้งไว้ · เลือกตัว is_default มาก่อน แล้วหมอปรับต่อได้
const sigs = Array.isArray(gp.sigs) ? gp.sigs : [];
const sig = sigs.find((s) => s && s.is_default) || sigs[0] || null;

if (sig) {
	setGroup({
		sig_dose: sig.sig_dose ?? null,
		sig_unit: code(sig.sig_unit || drug.disp_unit),
		sig_unit_label: text(sig.sig_unit || drug.disp_unit),
		sig_route: code(sig.sig_route),
		sig_route_label: text(sig.sig_route),
		sig_freq: code(sig.sig_freq),
		sig_freq_label: text(sig.sig_freq),
		sig_freq_calc: num(sig.sig_freq ? sig.sig_freq.calculate : 0) || null, // ครั้งต่อวัน — เก็บไว้คิด quantity ซ้ำตอนแก้ Sig
		sig_timing: code(sig.sig_timing),
		sig_timing_label: text(sig.sig_timing),
		sig_duration: sig.sig_duration ?? null,
		sig_label: sig.sig_label || null,
		sig_label_th: sig.sig_label_th || null,
		sig_label_custom: null,      // ที่หมอปรับเอง — เก็บแยกเพื่อให้เภสัชรู้ว่าแก้จากมาตรฐานตรงไหน
		sig_source: 'preset',
		sig_indication: sig.sig_indication || null,
		sig_note: sig.sig_note || null,
	});
} else {
	setF('sig_source', 'custom');
}

// ---------- 4) quantity = dose × ครั้งต่อวัน × จำนวนวัน (D7) ----------
// `calculate` เก็บเป็น string ('1' · '2') → ต้อง Number() ก่อนคูณ
// ความถี่ที่ไม่มีจำนวนครั้งแน่นอน (PRN) → calculate ว่าง/0 = ไม่คำนวณให้ ปล่อยหมอกรอกเอง
let qty = null;
if (sig) {
	const perDay = num(sig.sig_freq ? sig.sig_freq.calculate : 0);
	const dose = num(sig.sig_dose);
	const days = num(sig.sig_duration);
	if (perDay > 0 && dose > 0 && days > 0) qty = Math.ceil(dose * perDay * days);
}
if (qty) {
	setF('quantity', qty);
	setF('qty_calc_source', 'auto'); // หมอพิมพ์ทับ → onChange ของ quantity ตั้งเป็น 'manual' แล้วหยุดคิดให้
}

// ---------- 5) ราคาตามสิทธิ์ของใบ (D9) ----------
const price = pickPrice(drug.price_data, getOrderInscl());
const q = num(qty || 1);
const paid = Math.max(0, price.unit - price.claim);

setF('original_price', price.unit);
setF('unit_price', price.unit);
setF('claim_price', price.claim);
setF('paid_price', paid);
setF('net_amount', price.unit * q);
setF('claim_amount', price.claim * q);
setF('paid_amount', paid * q);
setF('is_price_overwrite', false);

// ---------- 6) ป้ายบนรายการ ----------
const tags = [];
const ctrl = text(gp.drug_control);
if (ctrl) tags.push(String(ctrl));
if (gp.drug_type && gp.drug_type.ed_status === 'ned') tags.push('NED');
if (drug.restricted) tags.push('RESTRICTED');
if (price.cash) tags.push('ไม่มีราคาตามสิทธิ์ — คิดแบบชำระเอง');
if (tags.length > 0) setF('item_tags', tags);

