const val = this.getValue();
const code = !!val ? val.value : null;

const labBox = this.getFieldRef('lab_box');
const xrayBox = this.getFieldRef('xray_box');

if (!!labBox) {
	code === 'lab' ? labBox.show() : labBox.hide();
}
if (!!xrayBox) {
	code === 'xray' ? xrayBox.show() : xrayBox.hide();
}

