const hasDose = (dose != null && dose !== ''), hasDur = (dur != null && dur !== '');

// ── ไทย → sig_label_th ──
{
  const route = TH(rRoute), unit = TH(rUnit), freq = TH(rFreq), timing = TH(rTiming);
  const p = [];
  let dp = ''; if (hasDose) dp = 'ครั้งละ ' + dose + (unit ? ' ' + unit : ''); else if (unit) dp = 'ครั้งละ ' + unit;
  if (route || dp) p.push((route || '') + dp);
  if (freq) p.push(freq);
  if (timing) p.push(timing);
  if (hasDur) p.push('เป็นเวลา ' + dur + ' วัน');
